# This is the main function and has references to all the forms
class Display_Main(tk.Tk):
    # This __init__ part of the code runs everytime
    def __init__(self):
        tk.Tk.__init__(self)
        # Pin every one of Tk's built-in NAMED default fonts (used by any
        # widget in this app that doesn't set font= explicitly, e.g. a
        # plain tk.Button/tk.Entry with no font kwarg) to a fixed pixel
        # size. Without this, those widgets' point-based default font gets
        # auto-converted using the real system DPI (now that this process
        # is DPI-aware - see top of file), which inflates them relative to
        # everything else in this app that DOES specify one of the
        # explicit Font_* constants above (already fixed the same way),
        # causing exactly this kind of overlap.
        import tkinter.font as _tkfont

        for _DefaultFontName in _tkfont.names():
            try:
                _DefaultFontObj = _tkfont.nametofont(_DefaultFontName)
                _OriginalPointSize = abs(_DefaultFontObj.cget("size"))
                _PixelSize = round(_OriginalPointSize * 96.0 / 72.0 * UI_SCALE)
                _DefaultFontObj.configure(size=-max(6, _PixelSize))
            except Exception:
                pass
        # Specify title of Form
        tk.Tk.wm_title(self, "Motion Analysis Center: Case Presentation")

        # Create a dictionary of frames/forms
        self.frames = {}
        frames = (TrialSelection_Page, GraphsDisplay_Page)
        # Specify all the form names
        for F in frames:
            frame = F(self)
            frame.grid(row=0, column=0, sticky="nsew")
            self.frames[F] = frame

        # Initialize the first form
        self.frames[TrialSelection_Page].tkraise()
        self.frames[TrialSelection_Page].build_UI()

    def _quit(self):
        self.destroy()


