        def SelectTrialsForRow(CurrentRow):
            SessionDirectory = (
                SessionDirectories[CurrentRow]
                if CurrentRow < len(SessionDirectories)
                else self.valueSessionDirectory[CurrentRow]
            )
            if not SessionDirectory or not os.path.isdir(SessionDirectory):
                tk.messagebox.showinfo(
                    "No session selected",
                    "Select a session directory before selecting trials.",
                )
                return

            _scan_dirs = [os.path.join(SessionDirectory, "GCD"), SessionDirectory] if os.path.isdir(os.path.join(SessionDirectory, "GCD")) else [SessionDirectory]
            _seen = set()
            TrialFiles = []
            for _sd in _scan_dirs:
                if os.path.isdir(_sd):
                    for file in os.listdir(_sd):
                        if file.lower().endswith(".gcd") and file.lower() not in _seen:
                            _seen.add(file.lower())
                            TrialFiles.append(file)
            TrialFiles = sorted(TrialFiles)[:20]
            TrialWindow = tk.Toplevel(self)
            TrialWindow.title("Select Dynamic Trials")
            TrialWindow.geometry("760x620")
            TrialWindow.transient(self)
            tk.Label(
                TrialWindow,
                text="Select up to 20 dynamic trials for this session.",
                anchor="w",
            ).pack(fill="x", padx=12, pady=(12, 8))
            TrialColumns = tk.Frame(TrialWindow)
            TrialColumns.pack(fill="both", expand=True, padx=12, pady=(0, 12))
            TrialVars = []
            ExistingTrials = set(SelectedTrialsByRow[CurrentRow])
            if not ExistingTrials:
                ExistingTrials = {
                    value
                    for value in (
                        getattr(self, "valueL1", ["--"] * NumRowsInGUI)[CurrentRow],
                        getattr(self, "valueL2", ["--"] * NumRowsInGUI)[CurrentRow],
                        getattr(self, "valueL3", ["--"] * NumRowsInGUI)[CurrentRow],
                        getattr(self, "valueL4", ["--"] * NumRowsInGUI)[CurrentRow],
                        getattr(self, "valueL5", ["--"] * NumRowsInGUI)[CurrentRow],
                    )
                    if value not in ("", "--")
                }
            for TrialFile in TrialFiles:
                TrialVar = tk.BooleanVar(
                    TrialWindow, value=TrialFile[:-4] in ExistingTrials or TrialFile in ExistingTrials
                )
                tk.Checkbutton(
                    TrialColumns,
                    text=TrialFile,
                    variable=TrialVar,
                    anchor="w",
                ).pack(fill="x")
                TrialVars.append((TrialFile, TrialVar))

            def SaveSelectedTrials():
                SelectedTrialsByRow[CurrentRow] = [
                    TrialFile[:-4]
                    for TrialFile, TrialVar in TrialVars
                    if TrialVar.get()
                ][:20]
                for EntryText, TrialName in zip(
                    (L1EntryText, L2EntryText, L3EntryText, L4EntryText, L5EntryText),
                    SelectedTrialsByRow[CurrentRow][:5],
                ):
                    EntryText[CurrentRow].set(TrialName)
                saveSettings()
                TrialWindow.destroy()

            tk.Button(
                TrialWindow,
                text="Save selected trials",
                command=SaveSelectedTrials,
            ).pack(pady=(0, 12))

        def RefreshExistingSessionRow(CurrentRow, SessionDirectory):
            SessionDirectories[CurrentRow] = SessionDirectory
            self.valueSessionDirectory[CurrentRow] = SessionDirectory
            SelectedTrialSessionDirectory[0] = SessionDirectory
            SelectedTrialsByRow[CurrentRow] = []
            if hasattr(self, "valueSelectedTrials"):
                self.valueSelectedTrials[CurrentRow] = []
            for AttributeName in (
                "valueL1", "valueL2", "valueL3", "valueL4", "valueL5",
                "valueR1", "valueR2", "valueR3", "valueR4", "valueR5",
            ):
                if hasattr(self, AttributeName):
                    getattr(self, AttributeName)[CurrentRow] = "--"

            MenuGroups = (
                (StaticEntry, StaticEntryText),
                (L1Entry, L1EntryText), (L2Entry, L2EntryText),
                (L3Entry, L3EntryText), (L4Entry, L4EntryText),
                (L5Entry, L5EntryText), (R1Entry, R1EntryText),
                (R2Entry, R2EntryText), (R3Entry, R3EntryText),
                (R4Entry, R4EntryText), (R5Entry, R5EntryText),
                (MRLeftEntry, MRLeftEntryText), (MRRightEntry, MRRightEntryText),
            )
            for EntryGroup, EntryTextGroup in MenuGroups:
                EntryGroup[CurrentRow]["menu"].delete(0, tk.END)
                EntryTextGroup[CurrentRow].set("--")
                EntryGroup[CurrentRow]["menu"].add_command(
                    label="--",
                    command=lambda values=EntryTextGroup: values[CurrentRow].set("--"),
                )

            _scan_dirs = [
                os.path.join(SessionDirectory, "GCD"),
                os.path.join(SessionDirectory, "Calibration"),
                SessionDirectory,
            ]
            _all_files = []
            _seen_files = set()
            for _sd in _scan_dirs:
                if os.path.isdir(_sd):
                    for _fn in os.listdir(_sd):
                        if _fn.lower() not in _seen_files:
                            _seen_files.add(_fn.lower())
                            _all_files.append(_fn)

            for FileName in sorted(_all_files):
                if FileName.lower().endswith(".gcd"):
                    TrialName = FileName[:-4]
                    for EntryGroup, EntryTextGroup in TrialGroups:
                        EntryGroup[CurrentRow]["menu"].add_command(
                            label=TrialName,
                            command=lambda value=TrialName, values=EntryTextGroup: values[
                                CurrentRow
                            ].set(value),
                        )
                elif FileName.lower().endswith(".py") and not FileName.startswith("Sitting"):
                    StaticEntry[CurrentRow]["menu"].add_command(
                        label=FileName,
                        command=lambda value=FileName: StaticEntryText[
                            CurrentRow
                        ].set(value),
                    )

