        def ReadGCD(GCDFileName):
            GCD_VariableNames = []
            GCD_VariableData = []
            if not GCDFileName[-6:-4] == "--":
                GCDfile = open(GCDFileName, "r")
                lines = GCDfile.readlines()
                VariableNameIndex = -1
                Keywords = ["#", "$", "!"]
                ReadTextParameterFlag = False
                for line in lines:
                    # Read C3d and Static File Name
                    if line[0] == "$":
                        ReadTextParameterFlag = True
                        GCD_VariableNames.append(line[1:-1])
                        GCD_VariableData.append([])
                        VariableNameIndex = VariableNameIndex + 1
                    if not any(x == line[0] for x in Keywords):
                        if ReadTextParameterFlag == True:
                            GCD_VariableData[VariableNameIndex].append(line[:-1])

                    # Read Computed Parameters
                    if line[0] == "!":
                        ReadTextParameterFlag = False
                        # GCD_VariableNames.append(line[1:-1])
                        GCD_VariableNames.append(line.split(" ")[0][1:].rstrip())
                        GCD_VariableName = line.split(" ")[0][1:].rstrip()
                        GCD_VariableData.append([])
                        VariableNameIndex = VariableNameIndex + 1
                    if not any(x == line[0] for x in Keywords):
                        if ReadTextParameterFlag == False:
                            if (
                                GCD_VariableName == "LeftStrideLength"
                                or GCD_VariableName == "RightStrideLength"
                                or GCD_VariableName == "LeftStepLength"
                                or GCD_VariableName == "RightStepLength"
                                or GCD_VariableName == "LeftSpeed"
                                or GCD_VariableName == "RightSpeed"
                            ):
                                GCD_VariableData[VariableNameIndex].append(
                                    float(line.split(" ")[0]) / 1000
                                )
                            else:
                                if (
                                    GCD_VariableName == "LeftCadence"
                                    or GCD_VariableName == "RightCadence"
                                ):
                                    GCD_VariableData[VariableNameIndex].append(
                                        2 * 60 * float(line.split(" ")[0])
                                    )
                                else:
                                    if (
                                        GCD_VariableName == "LeftOppositeFootOff"
                                        or GCD_VariableName == "LeftOppositeFootContact"
                                        or GCD_VariableName == "RightOppositeFootOff"
                                        or GCD_VariableName
                                        == "RightOppositeFootContact"
                                    ):
                                        # This function is only used for Run case
                                        # Set Opposite side temporal parameters to zero
                                        GCD_VariableData[VariableNameIndex].append(0)
                                    else:
                                        GCD_VariableData[VariableNameIndex].append(
                                            float(line.split(" ")[0])
                                        )
                                        # GCD_VariableData[VariableNameIndex].append(float(line[:-1]))
            if "StaticFileName" in GCD_VariableNames:
                StaticIndex = GCD_VariableNames.index("StaticFileName")
                StoredStaticName = os.path.basename(
                    str(GCD_VariableData[StaticIndex][0]).replace("\\", "/")
                )
                LocalStaticPath = os.path.join(
                    os.path.dirname(GCDFileName), StoredStaticName
                )
                if os.path.isfile(LocalStaticPath):
                    GCD_VariableData[StaticIndex] = [LocalStaticPath]
            return [GCD_VariableNames, GCD_VariableData]

        def ReadGCDComputeGDI(GCDFileName):
            GCD_VariableNames = []
            GCD_VariableData = []
            if not GCDFileName[-6:-4] == "--":
                GCDfile = open(GCDFileName, "r")
                lines = GCDfile.readlines()
                VariableNameIndex = -1
                Keywords = ["#", "$", "!"]
                ReadTextParameterFlag = False
                for line in lines:
                    # Read C3d and Static File Name
                    if line[0] == "$":
                        ReadTextParameterFlag = True
                        GCD_VariableNames.append(line[1:-1])
                        GCD_VariableData.append([])
                        VariableNameIndex = VariableNameIndex + 1
                    if not any(x == line[0] for x in Keywords):
                        if ReadTextParameterFlag == True:
                            GCD_VariableData[VariableNameIndex].append(line[:-1])

                    # Read Computed Parameters
                    if line[0] == "!":
                        ReadTextParameterFlag = False
                        # GCD_VariableNames.append(line[1:-1])
                        GCD_VariableNames.append(line.split(" ")[0][1:].rstrip())
                        GCD_VariableName = line.split(" ")[0][1:].rstrip()
                        GCD_VariableData.append([])
                        VariableNameIndex = VariableNameIndex + 1
                    if not any(x == line[0] for x in Keywords):
                        if ReadTextParameterFlag == False:
                            if (
                                GCD_VariableName == "LeftStrideLength"
                                or GCD_VariableName == "RightStrideLength"
                                or GCD_VariableName == "LeftStepLength"
                                or GCD_VariableName == "RightStepLength"
                                or GCD_VariableName == "LeftSpeed"
                                or GCD_VariableName == "RightSpeed"
                            ):
                                GCD_VariableData[VariableNameIndex].append(
                                    float(line.split(" ")[0]) / 1000
                                )
                            else:
                                if (
                                    GCD_VariableName == "LeftCadence"
                                    or GCD_VariableName == "RightCadence"
                                ):
                                    GCD_VariableData[VariableNameIndex].append(
                                        2 * 60 * float(line.split(" ")[0])
                                    )
                                else:
                                    GCD_VariableData[VariableNameIndex].append(
                                        float(line.split(" ")[0])
                                    )
                                    # GCD_VariableData[VariableNameIndex].append(float(line[:-1]))

                # =============================================================================
                #                 # If GDI not found in GCD file. Compute GDI
                # =============================================================================
                if "LeftGDI" in GCD_VariableNames:
                    pass
                else:
                    if "RightGDI" in GCD_VariableNames:
                        pass
                    else:
                        # Read GDI features and norms values from excel file
                        GDIFeaturesFile = xlrd.open_workbook(GDIFeaturesFileName)
                        GDIFeaturesFile_sheet = GDIFeaturesFile.sheet_by_name(
                            "GDI Calculations"
                        )
                        GDIFeatures = [[0.0 for m in range(15)] for n in range(459)]
                        for rowIndex in range(459):
                            for colIndex in range(15):
                                GDIFeatures[rowIndex][colIndex] = (
                                    GDIFeaturesFile_sheet.cell_value(
                                        rowIndex + 2, colIndex
                                    )
                                )
                        # print GDIFeatures

                        TDGDICoefficients = [0.0 for m in range(15)]
                        colIndex = 22
                        for rowIndex in range(15):
                            TDGDICoefficients[rowIndex] = (
                                GDIFeaturesFile_sheet.cell_value(rowIndex + 2, colIndex)
                            )
                        # print TDGDICoefficients

                        GDIMeanSDFile_sheet = GDIFeaturesFile.sheet_by_name(
                            "control feature data"
                        )
                        TDGDI_Mean = GDIMeanSDFile_sheet.cell_value(1, 52)
                        TDGDI_SD = GDIMeanSDFile_sheet.cell_value(1, 53)
                        # print TDGDI_Mean, TDGDI_SD

                        # Generate single column of kinematics for GDI computation
                        GDIKinematricsVariableNames = [
                            "PelvicTilt",
                            "PelvicObliquity",
                            "PelvicRotation",
                            "HipFlexExt",
                            "HipAbAdduct",
                            "HipRotation",
                            "KneeFlexExt",
                            "DorsiPlanFlex",
                            "FootRotation",
                        ]

                        # =============================================================================
                        # # Left
                        # =============================================================================
                        if "LeftDorsiPlanFlex" in GCD_VariableNames:
                            LeftGCDKinematicsVector = []
                            for GCDVariableName in GDIKinematricsVariableNames:
                                GCDVarIndex = GCD_VariableNames.index(
                                    "Left" + GCDVariableName
                                )
                                VariableData = GCD_VariableData[GCDVarIndex]
                                GCD_101TimePoint = np.linspace(
                                    0, len(VariableData) - 1, len(VariableData)
                                )
                                GCD_51TimePoints = np.linspace(
                                    0, len(VariableData) - 1, 51
                                )
                                VariabelData_51Points = np.interp(
                                    GCD_51TimePoints, GCD_101TimePoint, VariableData
                                )
                                for VariableDataIndex in range(
                                    len(VariabelData_51Points)
                                ):
                                    LeftGCDKinematicsVector.append(
                                        VariabelData_51Points[VariableDataIndex]
                                    )
                            # print LeftGCDKinematicsVector

                        # GDI needs the full gait cycle; skip if kinematics have gaps (NaN)
                        LeftGDI = None
                        if "LeftDorsiPlanFlex" in GCD_VariableNames and np.isnan(
                            LeftGCDKinematicsVector
                        ).any():
                            print(
                                "WARNING: Left GDI not computed for "
                                + GCDFileName
                                + " - kinematics contain missing (NaN) samples."
                            )
                        elif "LeftDorsiPlanFlex" in GCD_VariableNames:
                            # Next multiply kinematic vector (1x459) with each column of features matrix (459x15)to yield 15 coefficients
                            LeftGDICoefficients = [0.0 for m in range(15)]
                            for colIndex in range(15):
                                for rowIndex in range(459):
                                    LeftGDICoefficients[colIndex] = (
                                        LeftGDICoefficients[colIndex]
                                        + LeftGCDKinematicsVector[rowIndex]
                                        * GDIFeatures[rowIndex][colIndex]
                                    )
                            # print LeftGDICoefficients

                            # Find Distance between Coefficients
                            LeftEuclideanDistance = 0
                            for rowIndex in range(15):
                                LeftEuclideanDistance = (
                                    LeftEuclideanDistance
                                    + np.square(
                                        LeftGDICoefficients[rowIndex]
                                        - TDGDICoefficients[rowIndex]
                                    )
                                )
                            # print LeftEuclideanDistance

                            # Natural log of square root of distance
                            LeftGDI_Raw = np.log(np.sqrt(LeftEuclideanDistance))
                            # print LeftGDI_Raw

                            # Compute z-score using means and SD z =(raw-mean)/sd
                            LeftGDI_z = (LeftGDI_Raw - TDGDI_Mean) / TDGDI_SD
                            # print TDGDI_Mean, TDGDI_SD

                            # Scale the GDI Score
                            LeftGDI = int(round((100 - 10 * LeftGDI_z), 0))
                            # print LeftGDI

                        # =============================================================================
                        # # Right
                        # =============================================================================
                        if "RightDorsiPlanFlex" in GCD_VariableNames:
                            RightGCDKinematicsVector = []
                            for GCDVariableName in GDIKinematricsVariableNames:
                                GCDVarIndex = GCD_VariableNames.index(
                                    "Right" + GCDVariableName
                                )
                                VariableData = GCD_VariableData[GCDVarIndex]
                                GCD_101TimePoint = np.linspace(
                                    0, len(VariableData) - 1, len(VariableData)
                                )
                                GCD_51TimePoints = np.linspace(
                                    0, len(VariableData) - 1, 51
                                )
                                VariabelData_51Points = np.interp(
                                    GCD_51TimePoints, GCD_101TimePoint, VariableData
                                )
                                for VariableDataIndex in range(
                                    len(VariabelData_51Points)
                                ):
                                    RightGCDKinematicsVector.append(
                                        VariabelData_51Points[VariableDataIndex]
                                    )
                            # print RightGCDKinematicsVector

                        # GDI needs the full gait cycle; skip if kinematics have gaps (NaN)
                        RightGDI = None
                        if "RightDorsiPlanFlex" in GCD_VariableNames and np.isnan(
                            RightGCDKinematicsVector
                        ).any():
                            print(
                                "WARNING: Right GDI not computed for "
                                + GCDFileName
                                + " - kinematics contain missing (NaN) samples."
                            )
                        elif "RightDorsiPlanFlex" in GCD_VariableNames:
                            # Next multiply kinematic vector (1x459) with each column of features matrix (459x15)to yield 15 coefficients
                            RightGDICoefficients = [0.0 for m in range(15)]
                            for colIndex in range(15):
                                for rowIndex in range(459):
                                    RightGDICoefficients[colIndex] = (
                                        RightGDICoefficients[colIndex]
                                        + RightGCDKinematicsVector[rowIndex]
                                        * GDIFeatures[rowIndex][colIndex]
                                    )
                            # print RightGDICoefficients

                            # Find Distance between Coefficients
                            RightEuclideanDistance = 0
                            for rowIndex in range(15):
                                RightEuclideanDistance = (
                                    RightEuclideanDistance
                                    + np.square(
                                        RightGDICoefficients[rowIndex]
                                        - TDGDICoefficients[rowIndex]
                                    )
                                )
                            # print RightEuclideanDistance

                            # Natural log of square root of distance
                            RightGDI_Raw = np.log(np.sqrt(RightEuclideanDistance))
                            # print RightGDI_Raw

                            # Compute z-score using means and SD z =(raw-mean)/sd
                            RightGDI_z = (RightGDI_Raw - TDGDI_Mean) / TDGDI_SD
                            # print TDGDI_Mean, TDGDI_SD

                            # Scale the GDI Score
                            RightGDI = int(round((100 - 10 * RightGDI_z), 0))
                            # print RightGDI

                        # =============================================================================
                        # # Add to GCD FIle
                        # =============================================================================

                        GCDfile = open(GCDFileName, "a")
                        if LeftGDI is not None:
                            GCDfile.write("!LeftGDI\n")
                            GCDfile.write(str(LeftGDI) + "\n")
                            GCD_VariableNames.append("LeftGDI")
                            GCD_VariableData.append([str(LeftGDI)])
                        if RightGDI is not None:
                            GCDfile.write("!RightGDI\n")
                            GCDfile.write(str(RightGDI) + "\n")
                            GCD_VariableNames.append("RightGDI")
                            GCD_VariableData.append([str(RightGDI)])

            if "StaticFileName" in GCD_VariableNames:
                StaticIndex = GCD_VariableNames.index("StaticFileName")
                StoredStaticName = os.path.basename(
                    str(GCD_VariableData[StaticIndex][0]).replace("\\", "/")
                )
                LocalStaticPath = os.path.join(
                    os.path.dirname(GCDFileName), StoredStaticName
                )
                if os.path.isfile(LocalStaticPath):
                    GCD_VariableData[StaticIndex] = [LocalStaticPath]
            return [GCD_VariableNames, GCD_VariableData]

        def ReadAveGCD(GCDFileName):
            GCD_VariableNames = []
            GCD_VariableData = []
            GCD_VariableSD = []
            if os.path.isfile(GCDFileName) is True:
                GCDfile = open(GCDFileName, "r")
                lines = GCDfile.readlines()
                VariableNameIndex = -1
                Keywords = ["#", "$", "!"]
                ReadTextParameterFlag = False
                for line in lines:
                    # Read C3d and Static File Name
                    if line[0] == "$":
                        ReadTextParameterFlag = True
                        GCD_VariableNames.append(line[1:-1])
                        GCD_VariableData.append([])
                        GCD_VariableSD.append([])
                        VariableNameIndex = VariableNameIndex + 1
                    if not any(x == line[0] for x in Keywords):
                        if ReadTextParameterFlag == True:
                            GCD_VariableData[VariableNameIndex].append(line[:-1])

                    # Read Computed Parameters
                    if line[0] == "!":
                        ReadTextParameterFlag = False
                        GCD_VariableNames.append(str.split(line[1:-1], " ")[0])
                        GCD_VariableName = str.split(line[1:-1], " ")[0]
                        GCD_VariableData.append([])
                        GCD_VariableSD.append([])
                        VariableNameIndex = VariableNameIndex + 1
                    if not any(x == line[0] for x in Keywords):
                        if ReadTextParameterFlag == False:
                            if len(str.split(line[:-1], " ")) < 2:
                                if (
                                    GCD_VariableName == "StrideLength"
                                    or GCD_VariableName == "StepLength"
                                    or GCD_VariableName == "Speed"
                                ):
                                    GCD_VariableData[VariableNameIndex].append(
                                        float(str.split(line[:-1], " ")[0]) / 1000
                                    )
                                    GCD_VariableSD[VariableNameIndex].append(0)
                                else:
                                    if (
                                        GCD_VariableName == "LeftCadence"
                                        or GCD_VariableName == "RightCadence"
                                    ):
                                        GCD_VariableData[VariableNameIndex].append(
                                            2 * 60 * float(str.split(line[:-1], " ")[0])
                                        )
                                        GCD_VariableSD[VariableNameIndex].append(0)
                                    else:
                                        GCD_VariableData[VariableNameIndex].append(
                                            float(str.split(line[:-1], " ")[0])
                                        )
                                        GCD_VariableSD[VariableNameIndex].append(0)
                            else:
                                if (
                                    GCD_VariableName == "StrideLength"
                                    or GCD_VariableName == "StepLength"
                                    or GCD_VariableName == "Speed"
                                ):
                                    GCD_VariableData[VariableNameIndex].append(
                                        float(str.split(line[:-1], " ")[0]) / 1000
                                    )
                                    GCD_VariableSD[VariableNameIndex].append(
                                        float(str.split(line[:-1], " ")[1]) / 1000
                                    )
                                else:
                                    if (
                                        GCD_VariableName == "LeftCadence"
                                        or GCD_VariableName == "RightCadence"
                                    ):
                                        GCD_VariableData[VariableNameIndex].append(
                                            2 * 60 * float(str.split(line[:-1], " ")[0])
                                        )
                                        GCD_VariableSD[VariableNameIndex].append(
                                            float(2 * 60 * str.split(line[:-1], " ")[1])
                                        )
                                    else:
                                        GCD_VariableData[VariableNameIndex].append(
                                            float(str.split(line[:-1], " ")[0])
                                        )
                                        GCD_VariableSD[VariableNameIndex].append(
                                            float(str.split(line[:-1], " ")[1])
                                        )

            return [GCD_VariableNames, GCD_VariableData, GCD_VariableSD]

        def DrawplotAve(
            FrameHandle,
            X,
            Y,
            GraphsLineWidth,
            Ymin,
            Ymax,
            GraphTitle,
            Color,
            AspectRatio,
            PlotLength,
            TO,
            OpTO,
            OpFC,
            TO_LineWidth,
            normX,
            normY_Low,
            normY_High,
            normToeOff,
            normColor,
            normTransparency,
            Xlocation,
            Ylocation,
            valueDPI,
            XaxisLabelsFlag,
            YAxisTickLabel,
            YAxisTopLabel,
            YAxisTopLabelLocationX,
            YAxisTopLabelLocationY,
            YAxisBottomLabel,
            YAxisBottomLabelLocationX,
            YAxisBottomLabelLocationY,
            TitleFontSize,
            LabelFontSize,
        ):
            f = Figure(
                figsize=(PlotLength, AspectRatio * PlotLength),
                dpi=valueDPI * UI_SCALE,
            )
            f.patch.set_facecolor("w")
            a = f.add_subplot(111)
            for i in range(len(X)):
                (line1,) = a.plot(X[i], Y[i][0], Color[i], lw=GraphsLineWidth)
                Y_High = np.add(Y[i][0], Y[i][1])
                Y_Low = np.add(Y[i][0], -Y[i][1])
                a.fill_between(
                    X[i], Y_High, Y_Low, color=Color[i], alpha=dataTransparency
                )
                a.axvline(TO[i][0], lw=TO_LineWidth, color=Color[i])
                a.vlines(
                    OpTO[i][0],
                    Ymax,
                    Ymax - 0.05 * (Ymax - Ymin),
                    linewidth=TO_LineWidth,
                    color=Color[i],
                )
                a.vlines(
                    OpFC[i][0],
                    Ymax,
                    Ymax - 0.05 * (Ymax - Ymin),
                    linewidth=TO_LineWidth,
                    color=Color[i],
                )
                # Change Plot Spine Color if graphs is out of Y limits
                if min(Y[i][0]) > Ymax:
                    a.spines["top"].set_color(Color[i])
                if max(Y[i][0]) < Ymin:
                    a.spines["bottom"].set_color(Color[i])
                ######################################################
            a.fill_between(
                normX, normY_High, normY_Low, color=normColor, alpha=normTransparency
            )
            a.axvline(normToeOff, lw=TO_LineWidth, color=normColor)
            a.axhline(0, lw=0.5, color="black")
            a.set_xlim(0, 100)
            a.set_ylim(Ymin, Ymax)
            # Title
            a.set_title(
                GraphTitle, fontsize=TitleFontSize
            )  # , fontweight = 'bold',verticalalignment='baseline')
            # X Axis
            a.axes.get_xaxis().set_tick_params(direction="in")
            if XaxisLabelsFlag is True:
                a.axes.get_xaxis().set_ticks([0, 25, 50, 75, 100])
                a.axes.get_xaxis().set_ticklabels([0, 25, 50, 75, 100])
                # Decided to not add label since it changes the size of plot
                # a.axes.set_xlabel('% Gait Cycle',fontsize = 8)
            else:
                a.axes.get_xaxis().set_ticks([0, 25, 50, 75, 100])
                a.axes.get_xaxis().set_ticklabels([])
            # Y Axis
            a.axes.get_yaxis().set_ticks(YAxisTickLabel)
            a.axes.get_yaxis().set_ticklabels(YAxisTickLabel)
            a.axes.get_yaxis().set_tick_params(direction="in")
            # Y Axis Labels
            a.text(
                YAxisTopLabelLocationX,
                YAxisTopLabelLocationY,
                YAxisTopLabel,
                fontsize=LabelFontSize,
                horizontalalignment="right",
            )  # , fontweight = 'bold'
            a.text(
                YAxisBottomLabelLocationX,
                YAxisBottomLabelLocationY,
                YAxisBottomLabel,
                fontsize=LabelFontSize,
                horizontalalignment="right",
            )
            # Tick Font size
            a.tick_params(axis="x", which="major", labelsize=LabelFontSize)
            a.tick_params(axis="y", which="major", labelsize=LabelFontSize)
            # Location
            canvas = FigureCanvasTkAgg(f, master=FrameHandle)
            canvas.get_tk_widget().place(x=Xlocation, y=Ylocation)
            return canvas

