        def DrawplotZoom(
            FrameHandle,
            X,
            Y,
            GraphsLineWidth,
            Ymin,
            Ymax,
            GraphTitle,
            Color,
            AspectRatio,
            PlotLength,
            TO,
            OpTO,
            OpFC,
            TO_LineWidth,
            normX,
            normY_Low,
            normY_High,
            normToeOff,
            normColor,
            normTransparency,
            Xlocation,
            Ylocation,
            valueDPI,
            XaxisLabelsFlag,
            YAxisTickLabel,
            YAxisTopLabel,
            YAxisTopLabelLocationX,
            YAxisTopLabelLocationY,
            YAxisBottomLabel,
            YAxisBottomLabelLocationX,
            YAxisBottomLabelLocationY,
            TitleFontSize,
            LabelFontSize,
        ):
            f = Figure(
                figsize=(PlotLength, AspectRatio * PlotLength),
                dpi=valueDPI * UI_SCALE,
            )
            f.patch.set_facecolor("w")
            a = f.add_subplot(111)
            for i in range(len(X)):
                (line1,) = a.plot(X[i], Y[i], Color[i], lw=2 * GraphsLineWidth)
                a.axvline(TO[i], lw=TO_LineWidth, color=Color[i])
            a.fill_between(
                normX, normY_High, normY_Low, color=normColor, alpha=normTransparency
            )
            a.axvline(normToeOff, lw=TO_LineWidth, color=normColor)
            a.axhline(0, lw=0.5, color="black")
            a.set_xlim(0, 100)
            # a.set_ylim(Ymin,Ymax)
            # Modidy Graphs Upper and Lower limit
            YAxisTickLabel_modified = []
            for i in range(len(YAxisTickLabel)):
                YAxisTickLabel_modified.append(YAxisTickLabel[i])
            if min([min(sublist) for sublist in Y]) < Ymin:
                Ymin_modified = min([min(sublist) for sublist in Y])
                # while int(YAxisTickLabel_modified [0]) > Ymin_modified:
                #    YAxisTickLabel_modified .insert(0,int(YAxisTickLabel_modified [0]) - (int(YAxisTickLabel_modified [1])-int(YAxisTickLabel_modified [0])))
                while (YAxisTickLabel_modified[0]) > Ymin_modified:
                    YAxisTickLabel_modified.insert(
                        0,
                        round(
                            (
                                YAxisTickLabel_modified[0]
                                - (
                                    (YAxisTickLabel_modified[1])
                                    - (YAxisTickLabel_modified[0])
                                )
                            ),
                            2,
                        ),
                    )
            else:
                Ymin_modified = Ymin
            if max([max(sublist) for sublist in Y]) > Ymax:
                Ymax_modified = max([max(sublist) for sublist in Y])
                # while int(YAxisTickLabel_modified [-1]) < Ymax_modified:
                #    YAxisTickLabel_modified .append(int(YAxisTickLabel_modified [-1]) + (int(YAxisTickLabel_modified [-1])-int(YAxisTickLabel_modified [-2])))
                while (YAxisTickLabel_modified[-1]) < Ymax_modified:
                    YAxisTickLabel_modified.append(
                        round(
                            (
                                YAxisTickLabel_modified[-1]
                                + (
                                    (YAxisTickLabel_modified[-1])
                                    - (YAxisTickLabel_modified[-2])
                                )
                            ),
                            2,
                        )
                    )
            else:
                Ymax_modified = Ymax
            a.set_ylim(Ymin_modified, Ymax_modified)
            # Add Opposite foot off and Foot Contact
            Ymin_modified = YAxisTickLabel_modified[0]
            Ymax_modified = YAxisTickLabel_modified[-1]
            for i in range(len(X)):
                a.vlines(
                    OpTO[i],
                    Ymax_modified,
                    Ymax_modified - 0.05 * (Ymax_modified - Ymin_modified),
                    linewidth=TO_LineWidth,
                    color=Color[i],
                )
                a.vlines(
                    OpFC[i],
                    Ymax_modified,
                    Ymax_modified - 0.05 * (Ymax_modified - Ymin_modified),
                    linewidth=TO_LineWidth,
                    color=Color[i],
                )
            # Title
            a.set_title(
                GraphTitle, fontsize=TitleFontSize
            )  # , fontweight = 'bold',verticalalignment='baseline')
            # X Axis
            a.axes.get_xaxis().set_tick_params(direction="in")
            if XaxisLabelsFlag is True:
                a.axes.get_xaxis().set_ticks([0, 25, 50, 75, 100])
                a.axes.get_xaxis().set_ticklabels([0, 25, 50, 75, 100])
                # Decided to not add label since it changes the size of plot
                # a.axes.set_xlabel('% Gait Cycle',fontsize = 8)
            else:
                a.axes.get_xaxis().set_ticks([0, 25, 50, 75, 100])
                a.axes.get_xaxis().set_ticklabels([])
            # Y Axis
            a.axes.get_yaxis().set_ticks(YAxisTickLabel_modified)
            a.axes.get_yaxis().set_ticklabels(YAxisTickLabel_modified)
            a.axes.get_yaxis().set_tick_params(direction="in")
            # Y Axis Labels
            a.text(
                YAxisTopLabelLocationX,
                YAxisTopLabelLocationY,
                YAxisTopLabel,
                fontsize=LabelFontSize,
                horizontalalignment="right",
            )  # , fontweight = 'bold'
            a.text(
                YAxisBottomLabelLocationX,
                YAxisBottomLabelLocationY,
                YAxisBottomLabel,
                fontsize=LabelFontSize,
                horizontalalignment="right",
            )
            # Tick Font size
            a.tick_params(axis="x", which="major", labelsize=LabelFontSize)
            a.tick_params(axis="y", which="major", labelsize=LabelFontSize)
            # Location
            canvas = FigureCanvasTkAgg(f, master=FrameHandle)
            canvas.get_tk_widget().place(x=Xlocation, y=Ylocation)
            return canvas

