        def DrawplotEMG(
            FrameHandle,
            X,
            Y,
            GraphsLineWidth,
            Ymin,
            Ymax,
            GraphTitle,
            Color,
            AspectRatio,
            PlotLength,
            TO,
            OpTO,
            OpFC,
            TO_LineWidth,
            normX,
            normY_Low,
            normY_High,
            normToeOff,
            normColor,
            normTransparency,
            Xlocation,
            Ylocation,
            valueDPI,
            XaxisLabelsFlag,
            YAxisTickLabel,
            EMGBarStart,
            EMGBarEnd,
            TitleFontSize,
            LabelFontSize,
        ):
            f = Figure(
                figsize=(PlotLength, AspectRatio * PlotLength),
                dpi=valueDPI * UI_SCALE,
            )
            f.patch.set_facecolor("w")
            a = f.add_subplot(111)
            for i in range(len(X)):
                (line1,) = a.plot(X[i], Y[i], Color, lw=0.5 * GraphsLineWidth)
                a.axvline(TO[i], lw=TO_LineWidth, color=Color)
                a.vlines(
                    OpTO[i],
                    Ymax,
                    Ymax - 0.05 * (Ymax - Ymin),
                    linewidth=TO_LineWidth,
                    color=Color,
                )
                a.vlines(
                    OpFC[i],
                    Ymax,
                    Ymax - 0.05 * (Ymax - Ymin),
                    linewidth=TO_LineWidth,
                    color=Color,
                )
            a.fill_between(
                normX, normY_High, normY_Low, color=normColor, alpha=normTransparency
            )
            a.axvline(normToeOff, lw=TO_LineWidth, color=normColor)
            a.axhline(0, lw=0.5, color="black")
            a.set_xlim(0, 100)
            a.set_ylim(Ymin, Ymax)
            # Title
            a.set_title(
                GraphTitle, fontsize=TitleFontSize
            )  # , fontweight = 'bold',verticalalignment='baseline')
            # X Axis
            a.axes.get_xaxis().set_tick_params(direction="in")
            if XaxisLabelsFlag is True:
                a.axes.get_xaxis().set_ticks([0, 25, 50, 75, 100])
                a.axes.get_xaxis().set_ticklabels([0, 25, 50, 75, 100])
                # Decided to not add label since it changes the size of plot
                # a.axes.set_xlabel('% Gait Cycle',fontsize = 8)
            else:
                a.axes.get_xaxis().set_ticks([0, 25, 50, 75, 100])
                a.axes.get_xaxis().set_ticklabels([])
            # Y Axis
            a.axes.get_yaxis().set_ticks(YAxisTickLabel)
            a.axes.get_yaxis().set_ticklabels(YAxisTickLabel)
            a.axes.get_yaxis().set_tick_params(direction="in")
            # Tick Font size
            a.tick_params(axis="x", which="major", labelsize=LabelFontSize)
            a.tick_params(axis="y", which="major", labelsize=LabelFontSize)
            # Draw EMG normal boxes
            # Reactange((x,y),width,height)
            boxes = []
            for i in range(len(EMGBarStart)):
                box = Rectangle(
                    (EMGBarStart[i], -4.5), (EMGBarEnd[i] - EMGBarStart[i]), 0.5
                )
                boxes.append(box)
            pc = PatchCollection(boxes, facecolor="k")
            a.add_collection(pc)
            # Location
            canvas = FigureCanvasTkAgg(f, master=FrameHandle)
            canvas.get_tk_widget().place(x=Xlocation, y=Ylocation)
            return canvas

        def saveMRN():
            # Creates a Config.py file to pass MRN number to next page
            ConfigFileName = os.path.join(DisplaySettingsFileLocation, "Config.py")
            ConfigFile = open(ConfigFileName, "w+")
            ConfigFile.write("MRN=" + "'" + str(MRN) + "'" + "\n")
            ConfigFile.close()

        def ReadMRN():
            # Extract MRN from previous Form
            MRN = ""
            try:
                ConfigFileName = os.path.join(DisplaySettingsFileLocation, "Config.py")
                ConfigFile = open(ConfigFileName, "r")
                lines = ConfigFile.readlines()
                MRN = lines[0].split("=")[1].split("\n")[0].strip("'")
                ConfigFile.close()
                os.remove(ConfigFileName)
            except:
                "Config File Not Found"
            return MRN

        MRN = ReadMRN()

        # =============================================================================
        #         OpenPatientDirectory
        # =============================================================================
        def OpenPatientDirectory():
            # Default
            PatientDirectoryString = InitialPathForPdf / (str(MRN) + "/")

            # Greenville Folder Structure
            if UseGreenvilleFolderStructure == True:
                if MRN == "246" or MRN == "245":
                    PatientDirectoryString = InitialPathForPdf / (
                        "MAL Records "
                        + str(MRN)[:3]
                        + "/"
                        + self.valuePatientNumber[:4]
                        + "000/"
                        + str(MRN)
                        + "/"
                    )
                else:
                    PatientDirectoryString = (
                        InitialPathForPdf / "MAL Records " / str(MRN)[:3] / str(MRN)
                    )
            os.startfile(PatientDirectoryString)

        # Read Page Settings
        exec(open("KinematicsPageSettings.py").read())
        LeftAngleNames = self.LeftAngleNames
        RightAngleNames = self.RightAngleNames
        AngleTitles = self.AngleTitles
        AnglesYLabels = self.AnglesYLabels
        global \
            AngleUpperLimit, \
            AngleLowerLimit, \
            YAxisTickLabels, \
            YLabelOffsetsYTop, \
            YLabelOffsetsYBottom
        AngleUpperLimit = self.AngleUpperLimit
        AngleLowerLimit = self.AngleLowerLimit
        YAxisTickLabels = self.YAxisTickLabels
        YLabelOffsetsXTop = self.YLabelOffsetsXTop
        YLabelOffsetsYTop = self.YLabelOffsetsYTop
        YLabelOffsetsXBottom = self.YLabelOffsetsXBottom
        YLabelOffsetsYBottom = self.YLabelOffsetsYBottom
        AnglesUnitLabels = self.AnglesUnitLabels

        exec(open("SagittalKineticsPageSettings.py").read())
        LeftSagittalKineticsNames = self.LeftSagittalKineticsNames
        RightSagittalKineticsNames = self.RightSagittalKineticsNames
        SagittalKineticsTitles = self.SagittalKineticsTitles
        SagittalKineticsYLabels = self.SagittalKineticsYLabels
        global \
            SagittalKineticsUpperLimit, \
            SagittalKineticsLowerLimit, \
            SagittalKineticsYAxisTickLabels, \
            SagittalKineticsYLabelOffsetsYTop, \
            SagittalKineticsYLabelOffsetsYBottom
        SagittalKineticsUpperLimit = self.SagittalKineticsUpperLimit
        SagittalKineticsLowerLimit = self.SagittalKineticsLowerLimit
        SagittalKineticsYAxisTickLabels = self.SagittalKineticsYAxisTickLabels
