            # Disable buttons if Foot kinetics data not found
            if (
                "LeftAnkleComplexDorsiPlanFlex" in L1_VariableNames
                or "LeftAnkleComplexDorsiPlanFlex" in L2_VariableNames
                or "LeftAnkleComplexDorsiPlanFlex" in L3_VariableNames
                or "LeftAnkleComplexDorsiPlanFlex" in L4_VariableNames
                or "LeftAnkleComplexDorsiPlanFlex" in L5_VariableNames
            ):
                pass
            else:
                LeftFootKinematics = False
                DisplayLeftFootKinematicsButton.configure(state=tk.DISABLED)
                ConditionComparisonDisplayLeftFootKinematicsButton.configure(
                    state=tk.DISABLED
                )
            if (
                "RightAnkleComplexDorsiPlanFlex" in R1_VariableNames
                or "RightAnkleComplexDorsiPlanFlex" in R2_VariableNames
                or "RightAnkleComplexDorsiPlanFlex" in R3_VariableNames
                or "RightAnkleComplexDorsiPlanFlex" in R4_VariableNames
                or "RightAnkleComplexDorsiPlanFlex" in R5_VariableNames
            ):
                pass
            else:
                RightFootKinematics = False
                DisplayRightFootKinematicsButton.configure(state=tk.DISABLED)
