            # Change Condition Comparison rows to default black color
            for ConditionRow in range(len(self.valueAnalysisDate)):
                ConditionComparisonCheckButtons[ConditionRow].configure(fg="black")

            row = TestingConditionIndex.get()
            LoadGCDFilesForSpecifiedRow(row)
            global NormVariableNames, NormVariableData, NormVariableSD
            # Plot Multiple GCD
            PlottingVariableNames = []
            PlottingVariableData = []
