                # Compute Norms (Placeholder to compute zeros for Norm values)
                # NormAngle = Angle[4:] # Remove 'Left' from Variable Name
                # Find the Norm EMG Envelope computed from SLC TD data
                global NormVariableNames, NormVariableData, NormVariableSD
                global EMGOnOffBarStart, EMGOnOffBarEnd
                NormAngle = NormEMGEnvelopeNames[AngleIndex]
                try:
                    NormGCDVarIndex = NormVariableNames.index(NormAngle)
                    normY = NormVariableData[NormGCDVarIndex]
                    normX = np.linspace(0, 100, len(normY))
                    normY_High = np.linspace(0, 0, len(normY))
                    normY_Low = np.linspace(0, 0, len(normY))
                    NormEMGOffset = 0.06
                    for i in range(len(normY)):
                        normY_High[i] = normY[i]
                        PeakEMGSignal = max(normY)
                        if (
                            (normY[i] - NormEMGOffset)
                            * 4
                            / (PeakEMGSignal - NormEMGOffset)
                        ) > 0:
                            normY_High[i] = (
                                (normY[i] - NormEMGOffset)
                                * 4
                                / (PeakEMGSignal - NormEMGOffset)
                            )
                except:
                    # Data not found in GCD file
                    normX = np.linspace(0, 100, 101)
                    normY = np.linspace(0, 0, 101)
                    normY_High = np.linspace(0, 0, 101)
                    normY_Low = np.linspace(0, 0, 101)

