        def savePdf(PdfType):
            def PrintPlot(
                PageHandle,
                X,
                Y,
                GraphsLineWidth,
                Ymin,
                Ymax,
                GraphTitle,
                Color,
                AspectRatio,
                PrintPlotLength,
                TO,
                OpTO,
                OpFC,
                TO_LineWidth,
                normX,
                normY_Low,
                normY_High,
                normColor,
                normTransparency,
                Xlocation,
                Ylocation,
                valueDPI,
                XaxisLabelsFlag,
                YAxisTickLabel,
                YAxisTopLabel,
                YAxisTopLabelLocationX,
                YAxisTopLabelLocationY,
                YAxisBottomLabel,
                YAxisBottomLabelLocationX,
                YAxisBottomLabelLocationY,
                TitleFontSize,
                LabelFontSize,
            ):
                f = Drawing(
                    PrintPlotLength * inch, AspectRatio * PrintPlotLength * inch
                )
                a = LinePlot()
                a.behindAxes = 0
                # X Y positions are set to zero here, Plot location is specifed in renderPdf
                a.x = 0
                a.y = 0
                a.height = AspectRatio * PrintPlotLength * inch  # * valueDPI
                a.width = PrintPlotLength * inch  # * valueDPI

                # Combine plot data into list of [x,y] lists
                Data_Combined = []
                # Add norm
                Data_Combined.append(np.column_stack((normX, normY_High)).tolist())
                Data_Combined.append(np.column_stack((normX, normY_Low)).tolist())
                # Add X Axis
                Data_Combined.append([[0, 0], [100, 0]])

                # Add Subject Data
                for i in range(len(X)):
                    # Truncate data by Graph Limits
                    # Also changes the spine color if all values are beyong Ymin or Ymax
                    for j in range(len(Y[i])):
                        if Y[i][j] > Ymax:
                            Y[i][j] = Ymax
                        if Y[i][j] < Ymin:
                            Y[i][j] = Ymin
                    # Add Data
                    Data_Combined.append(np.column_stack((X[i], Y[i])).tolist())
                    # Add ToeOff Line
                    Data_Combined.append([[TO[i][0], Ymin], [TO[i][0], Ymax]])
                    # Add Oppostive Foot Off and Foot Contact
                    Data_Combined.append(
                        [[OpTO[i][0], Ymin + 0.95 * (Ymax - Ymin)], [OpTO[i][0], Ymax]]
                    )
                    Data_Combined.append(
                        [[OpFC[i][0], Ymin + 0.95 * (Ymax - Ymin)], [OpFC[i][0], Ymax]]
                    )
                a.data = Data_Combined
                # Set axes Ticks
                a.xValueAxis.tickDown = 2
                a.xValueAxis.tickUp = 5
                a.yValueAxis.tickLeft = 2
                a.yValueAxis.tickRight = 0
                # Set StrokedWith for box outline and axes
                a.strokeWidth = GraphsLineWidth * 0.5
                a.strokeColor = reportlabColors.black
                a.xValueAxis.strokeWidth = GraphsLineWidth * 0.5
                a.yValueAxis.strokeWidth = GraphsLineWidth * 0.5
                # Set axes limits
                a.yValueAxis.valueMin = Ymin
                a.yValueAxis.valueMax = Ymax
                a.yValueAxis.valueStep = YAxisTickLabel[1] - YAxisTickLabel[0]
                a.yValueAxis.labels.fontSize = LabelFontSize
                a.xValueAxis.valueMin = 0
                a.xValueAxis.valueMax = 100
                a.xValueAxis.valueStep = 25
                a.xValueAxis.labels.fontSize = LabelFontSize
                if XaxisLabelsFlag == True:
                    a.xValueAxis.visibleLabels = True
                else:
                    a.xValueAxis.visibleLabels = False

                a.yValueAxis.drawGridLast = True

                # Set Line Colors
                # Norms
                a.lines[0].strokeColor = reportlabColors.lightgrey
                a.lines[0].strokeWidth = 1
                a.lines[0].inFill = True  # Changes to area plot
                a.lines[1].strokeColor = reportlabColors.white
                a.lines[1].strokeWidth = 1
                a.lines[1].inFill = True  # Changes to area plot
                # X-axis
                if Ymin < 0:
                    a.lines[2].strokeColor = reportlabColors.black
                else:  # Remove X axis for muscle length
                    a.lines[2].strokeColor = reportlabColors.white
                a.lines[2].strokeWidth = GraphsLineWidth * 0.5
                # Data Lines
                reportlabColorList = [
                    reportlabColors.red,
                    reportlabColors.blue,
                    reportlabColors.green,
                    reportlabColors.magenta,
                    reportlabColors.brown,
                ]
                DataLineIndex = 3
                for i in range(len(X)):
                    # Data Line
                    a.lines[DataLineIndex].strokeColor = reportlabColorList[i]
                    a.lines[DataLineIndex].strokeWidth = GraphsLineWidth
                    DataLineIndex = DataLineIndex + 1
                    # ToeOff Line
                    a.lines[DataLineIndex].strokeColor = reportlabColorList[i]
                    a.lines[DataLineIndex].strokeWidth = TO_LineWidth
                    DataLineIndex = DataLineIndex + 1
                    # OppositeToeOff Line
                    a.lines[DataLineIndex].strokeColor = reportlabColorList[i]
                    a.lines[DataLineIndex].strokeWidth = TO_LineWidth
                    DataLineIndex = DataLineIndex + 1
                    # OppositeFootContact Line
                    a.lines[DataLineIndex].strokeColor = reportlabColorList[i]
                    a.lines[DataLineIndex].strokeWidth = TO_LineWidth
                    DataLineIndex = DataLineIndex + 1

                # Add plot to drawing
                f.add(a)
                # Redraw the plot outline since it gets covered by area plots
                f.add(
                    Rect(
                        0,
                        0,
                        PrintPlotLength * inch,
                        AspectRatio * PrintPlotLength * inch,
                        strokeWidth=GraphsLineWidth * 0.5,
                        fillColor=None,
                    )
                )
                # Print drawing on the Page
                renderPDF.draw(f, PageHandle, Xlocation, Ylocation, showBoundary=False)

                # Add Y Axis Labels
                PageHandle.setFont("Times-Roman", LabelFontSize)
                PageHandle.drawRightString(
                    Xlocation - 2,
                    Ylocation + AspectRatio * PrintPlotLength * inch - 12,
                    YAxisTopLabel,
                )
                PageHandle.drawRightString(
                    Xlocation - 2, Ylocation + 8, YAxisBottomLabel
                )

                # Add Title
                PageHandle.setFont("Times-Bold", TitleFontSize)
                PageHandle.drawCentredString(
                    Xlocation + PrintPlotLength / 2 * inch,
                    Ylocation + AspectRatio * PrintPlotLength * inch + 2,
                    GraphTitle,
                )
                if XaxisLabelsFlag == True:
                    # Add X Axis Label
                    PageHandle.setFont("Times-Roman", LabelFontSize)
                    PageHandle.drawCentredString(
                        Xlocation + PrintPlotLength / 2 * inch,
                        Ylocation - 20,
                        "% Gait Cycle",
                    )
                else:
                    a.xValueAxis.visibleLabels = False

            def PrintPlotAve(
                PageHandle,
                X,
                Y,
                GraphsLineWidth,
                Ymin,
                Ymax,
                GraphTitle,
                Color,
                AspectRatio,
                PrintPlotLength,
                TO,
                OpTO,
                OpFC,
                TO_LineWidth,
                normX,
                normY_Low,
                normY_High,
                normColor,
                normTransparency,
                Xlocation,
                Ylocation,
                valueDPI,
                XaxisLabelsFlag,
                YAxisTickLabel,
                YAxisTopLabel,
                YAxisTopLabelLocationX,
                YAxisTopLabelLocationY,
                YAxisBottomLabel,
                YAxisBottomLabelLocationX,
                YAxisBottomLabelLocationY,
                TitleFontSize,
                LabelFontSize,
            ):
                f = Drawing(
                    PrintPlotLength * inch, AspectRatio * PrintPlotLength * inch
                )
                a = LinePlot()
                a.behindAxes = 0
                # X Y positions are set to zero here, Plot location is specifed in renderPdf
                a.x = 0
                a.y = 0
                a.height = AspectRatio * PrintPlotLength * inch  # * valueDPI
                a.width = PrintPlotLength * inch  # * valueDPI

                # Combine plot data into list of [x,y] lists
                Data_Combined = []
                # Add norm
                Data_Combined.append(np.column_stack((normX, normY_High)).tolist())
                Data_Combined.append(np.column_stack((normX, normY_Low)).tolist())
                # Add X Axis
                Data_Combined.append([[0, 0], [100, 0]])

                # Add Subject Data
                for i in range(len(X)):
                    # Truncate data by Graph Limits
                    # Also changes the spine color if all values are beyong Ymin or Ymax
                    Y_High = np.add(Y[i][0], Y[i][1])
                    Y_Low = np.add(Y[i][0], -Y[i][1])
                    for j in range(len(Y[i][0])):
                        if Y[i][0][j] > Ymax:
                            Y[i][0][j] = Ymax
                        if Y[i][0][j] < Ymin:
                            Y[i][0][j] = Ymin
                        if Y_High[j] > Ymax:
                            Y_High[j] = Ymax
                        if Y_High[j] < Ymin:
                            Y_High[j] = Ymin
                        if Y_Low[j] > Ymax:
                            Y_Low[j] = Ymax
                        if Y_Low[j] < Ymin:
                            Y_Low[j] = Ymin
                    # Add Data
                    Data_Combined.append(np.column_stack((X[i], Y[i][0])).tolist())
                    # Add Upper SD
                    Data_Combined.append(np.column_stack((X[i], Y_High)).tolist())
                    # Add Lower SD
                    Data_Combined.append(np.column_stack((X[i], Y_Low)).tolist())
                    # Add ToeOff Line
                    Data_Combined.append([[TO[i][0], Ymin], [TO[i][0], Ymax]])
                    # Add Oppostive Foot Off and Foot Contact
                    Data_Combined.append(
                        [[OpTO[i][0], Ymin + 0.95 * (Ymax - Ymin)], [OpTO[i][0], Ymax]]
                    )
                    Data_Combined.append(
                        [[OpFC[i][0], Ymin + 0.95 * (Ymax - Ymin)], [OpFC[i][0], Ymax]]
                    )
                a.data = Data_Combined
                # Set axes Ticks
                a.xValueAxis.tickDown = 2
                a.xValueAxis.tickUp = 5
                a.yValueAxis.tickLeft = 2
                a.yValueAxis.tickRight = 0
                # Set StrokedWith for box outline and axes
                a.strokeWidth = GraphsLineWidth * 0.5
                a.strokeColor = reportlabColors.black
                a.xValueAxis.strokeWidth = GraphsLineWidth * 0.5
                a.yValueAxis.strokeWidth = GraphsLineWidth * 0.5
                # Set axes limits
                a.yValueAxis.valueMin = Ymin
                a.yValueAxis.valueMax = Ymax
                a.yValueAxis.valueStep = YAxisTickLabel[1] - YAxisTickLabel[0]
                a.yValueAxis.labels.fontSize = LabelFontSize
                a.xValueAxis.valueMin = 0
                a.xValueAxis.valueMax = 100
                a.xValueAxis.valueStep = 25
                a.xValueAxis.labels.fontSize = LabelFontSize
                if XaxisLabelsFlag == True:
                    a.xValueAxis.visibleLabels = True
                else:
                    a.xValueAxis.visibleLabels = False

                a.yValueAxis.drawGridLast = True

                # Set Line Colors
                # Norms
                a.lines[0].strokeColor = reportlabColors.lightgrey
                a.lines[0].strokeWidth = 1
                a.lines[0].inFill = True  # Changes to area plot
                a.lines[1].strokeColor = reportlabColors.white
                a.lines[1].strokeWidth = 1
                a.lines[1].inFill = True  # Changes to area plot
                # X-axis
                if Ymin < 0:
                    a.lines[2].strokeColor = reportlabColors.black
                else:  # Remove X axis for muscle length
                    a.lines[2].strokeColor = reportlabColors.white
                a.lines[2].strokeWidth = GraphsLineWidth * 0.5

                # Data Lines
                reportlabColorList = [
                    reportlabColors.red,
                    reportlabColors.blue,
                    reportlabColors.green,
                    reportlabColors.magenta,
                    reportlabColors.brown,
                ]
                DataLineIndex = 3
                for i in range(len(X)):
                    # Data Line
                    a.lines[DataLineIndex].strokeColor = reportlabColorList[i]
                    a.lines[DataLineIndex].strokeWidth = GraphsLineWidth
                    DataLineIndex = DataLineIndex + 1
                    # Data Upper SD
