                PageHandle.drawCentredString(
                    PageWidth / 2, PageHeight - HeightMargin - 0.3 * inch, PageTitle
                )
                PageHandle.setFillColor(reportlabColors.black)

                # Plot Multiple GCD
                PlottingVariableNames = []
                PlottingVariableData = []
                if not len(L1_VariableNames) == 0:
                    PlottingVariableNames.append(L1_VariableNames)
                if not len(L2_VariableNames) == 0:
                    PlottingVariableNames.append(L2_VariableNames)
                if not len(L3_VariableNames) == 0:
                    PlottingVariableNames.append(L3_VariableNames)
                if not len(L4_VariableNames) == 0:
                    PlottingVariableNames.append(L4_VariableNames)
                if not len(L5_VariableNames) == 0:
                    PlottingVariableNames.append(L5_VariableNames)
                if not len(L1_VariableData) == 0:
                    PlottingVariableData.append(L1_VariableData)
                if not len(L2_VariableData) == 0:
                    PlottingVariableData.append(L2_VariableData)
