            def ConditionComparisonPrintRightAve(
                PageHandle,
                PlotSpaceOriginX,
                PlotSpaceOriginY,
                PlotSpacingX,
                PlotSpacingY,
                RightVariableNames,
                GraphsYAxisTickLabels,
                GraphsLowerLimits,
                GraphsUpperLimits,
                GraphsTitles,
                GraphsYLabels,
                GraphsYLabelOffsetsXTop,
                GraphsYLabelOffsetsYTop,
                GraphsYLabelOffsetsXBottom,
                GraphsYLabelOffsetsYBottom,
                VariableUnitLabels,
                PageTitle,
            ):
                TotalActiveRows = 0
                RowSelection = []
                for ConditionRow in range(len(self.valueAnalysisDate)):
                    RowSelection.append(
                        ConditionComparisonCheckVariables[ConditionRow].get()
                    )
                    if ConditionComparisonCheckVariables[ConditionRow].get() == 1:
                        TotalActiveRows = TotalActiveRows + 1

                # Update MR trial selection Here
                UpdateMRTrialSelection()

                # Plot Multiple GCD
                exec(open(PatientDisplaySettingsFileName).read())
                PlottingVariableNames = []
                PlottingVariableData = []
                RightToeOff = []
                RightOppositeToeOff = []
                RightOppositeHeelContact = []
                StaticFileNames = []
                C3DFileNames = []
                Speeds = []
                RightGDIs = []
                ActiveRowColorList = []
                # Assign Color by Display Order if selected
                ColorCodeIndex = 0
                DisplayOrderIndex = 0
                ColorCodeIndexByRow = [0 for m in range(len(self.valueAnalysisDate))]
                for i in range(TotalActiveRows):
                    ActiveRowColorList.append("black")
                while ColorCodeIndex < TotalActiveRows:
                    ActiveRowNum = 0
                    for ConditionRow in range(len(self.valueAnalysisDate)):
                        if RowSelection[ConditionRow] == 1:
                            if DisplayOrderByRow[ConditionRow] == DisplayOrderIndex:
                                ActiveRowColorList[ActiveRowNum] = ColorList[
                                    ColorCodeIndex
                                ]
                                ColorCodeIndexByRow[ConditionRow] = ColorCodeIndex
                                ColorCodeIndex = ColorCodeIndex + 1
                            ActiveRowNum = ActiveRowNum + 1
                    DisplayOrderIndex = DisplayOrderIndex + 1
                ##############################################

                # Extract Average Values
                def ExtractRightAve(VariableName):
                    # Right
                    Right_VariableName = "Right" + VariableName
                    RightValues = []
                    if Right_VariableName in R1_VariableNames:
                        RightValues.append(
                            R1_VariableData[R1_VariableNames.index(Right_VariableName)][
                                0
                            ]
                        )
                    if Right_VariableName in R2_VariableNames:
                        RightValues.append(
                            R2_VariableData[R2_VariableNames.index(Right_VariableName)][
                                0
                            ]
                        )
                    if Right_VariableName in R3_VariableNames:
                        RightValues.append(
                            R3_VariableData[R3_VariableNames.index(Right_VariableName)][
                                0
                            ]
                        )
                    if Right_VariableName in R4_VariableNames:
                        RightValues.append(
                            R4_VariableData[R4_VariableNames.index(Right_VariableName)][
                                0
                            ]
                        )
                    if Right_VariableName in R5_VariableNames:
                        RightValues.append(
                            R5_VariableData[R5_VariableNames.index(Right_VariableName)][
                                0
                            ]
                        )

                    if RightValues == []:
                        Ave_RightValues = 0
                        SD_RightValues = 0
                    else:
                        Ave_RightValues = np.average(RightValues, axis=0)
                        SD_RightValues = np.std(RightValues, axis=0)
                    Right_AveData = [Ave_RightValues, SD_RightValues]

                    return Right_AveData

                NumActiveRows = 0
                RightNumOfSamplesinConditions = []
                for ConditionRow in range(len(self.valueAnalysisDate)):
                    if RowSelection[ConditionRow] == 1:
                        LoadGCDFilesForSpecifiedRow(ConditionRow)
                        # Compute Average for Variables
                        # Right
                        Right_VariableData = []
                        RightNumOfSamples = 0
                        for RightVariableName in RightVariableNames:
                            RightValues = []
                            if not RightVariableName == "":
                                if RightVariableName in R1_VariableNames:
                                    RightValues.append(
                                        R1_VariableData[
                                            R1_VariableNames.index(RightVariableName)
                                        ]
                                    )
                                if RightVariableName in R2_VariableNames:
                                    RightValues.append(
                                        R2_VariableData[
                                            R2_VariableNames.index(RightVariableName)
                                        ]
                                    )
                                if RightVariableName in R3_VariableNames:
                                    RightValues.append(
                                        R3_VariableData[
                                            R3_VariableNames.index(RightVariableName)
                                        ]
                                    )
                                if RightVariableName in R4_VariableNames:
                                    RightValues.append(
                                        R4_VariableData[
                                            R4_VariableNames.index(RightVariableName)
                                        ]
                                    )
                                if RightVariableName in R5_VariableNames:
                                    RightValues.append(
                                        R5_VariableData[
                                            R5_VariableNames.index(RightVariableName)
                                        ]
                                    )
                                if RightNumOfSamples < len(RightValues):
                                    RightNumOfSamples = len(RightValues)
                            if RightValues == []:
                                Ave_RightValues = np.linspace(0, 0, 101)
                                SD_RightValues = np.linspace(0, 0, 101)
                            else:
                                Ave_RightValues = np.average(RightValues, axis=0)
                                SD_RightValues = np.std(RightValues, axis=0)
                            Right_VariableData.append([Ave_RightValues, SD_RightValues])
                        RightNumOfSamplesinConditions.append(RightNumOfSamples)
                        PlottingVariableNames.append(RightVariableNames)
                        PlottingVariableData.append(Right_VariableData)

                        RightToeOffAveSD = ExtractRightAve("FootOff")
                        RightToeOff.append(RightToeOffAveSD)
                        RightOppositeToeOffAveSD = ExtractRightAve("OppositeFootOff")
                        RightOppositeToeOff.append(RightOppositeToeOffAveSD)
                        RightOppositeHeelContactAveSD = ExtractRightAve(
                            "OppositeFootContact"
                        )
                        RightOppositeHeelContact.append(RightOppositeHeelContactAveSD)
                        SpeedsAveSD = ExtractRightAve("Speed")
                        Speeds.append(SpeedsAveSD)
                        RightGDIsAveSD = ExtractRightAve("GDI")
